  "Memory: colour, normal and roughness maps, block-compressed, with mipmaps.": { ca: "Memòria: mapes de color, normal i roughness, comprimits per blocs, amb mipmaps.", es: "Memoria: mapas de color, normal y roughness, comprimidos por bloques, con mipmaps." },
