  "Fit to Trim: {s}.": { ca: "Fit to Trim: {s}.", es: "Fit to Trim: {s}." },
  "✓ {n} fits its strip.": { ca: "✓ {n} encaixa a la seva franja.", es: "✓ {n} encaja en su franja." },
  "Follow Active Quads: the islands are straight strips now.": { ca: "Follow Active Quads: ara les illes són tires rectes.", es: "Follow Active Quads: ahora las islas son tiras rectas." },
  "Align Rotation: the islands are lined up with the axes.": { ca: "Align Rotation: les illes estan alineades amb els eixos.", es: "Align Rotation: las islas están alineadas con los ejes." },
