  "Model every piece at its real size inside its band. Keep the relief shallow: a normal map stores directions, not depth, so deep undercuts never read well.": { ca: "Modela cada peça a la seva mida real dins de la seva banda. Mantén el relleu poc profund: un normal map guarda direccions, no profunditat, i els entrants profunds no es llegeixen mai bé.", es: "Modela cada pieza a su tamaño real dentro de su banda. Mantén el relieve poco profundo: un normal map guarda direcciones, no profundidad, y los entrantes profundos nunca se leen bien." },
  "Bake Type is not Normal: this is a lit render, not a normal map.": { ca: "El Bake Type no és Normal: això és un render il·luminat, no un normal map.", es: "El Bake Type no es Normal: esto es un render iluminado, no un normal map." },
  "Selected to Active is off: the plane baked its own flat normals.": { ca: "Selected to Active està desactivat: el pla ha fet el bake de les seves pròpies normals planes.", es: "Selected to Active está desactivado: el plano ha hecho el bake de sus propias normales planas." },
  "Extrusion too small: the tops of {s} are cut flat.": { ca: "Extrusion massa petita: la part de dalt de {s} queda tallada i plana.", es: "Extrusion demasiado pequeña: la parte de arriba de {s} queda cortada y plana." },
  "Max Ray Distance is shorter than the extrusion: the joints and grooves are lost.": { ca: "La Max Ray Distance és més curta que l'extrusió: es perden les juntes i les ranures.", es: "La Max Ray Distance es más corta que la extrusión: se pierden las juntas y las ranuras." },
  "The image is {s} px: the plan is a 1024 sheet.": { ca: "La imatge és de {s} px: el pla és un full de 1024.", es: "La imagen es de {s} px: el plan es una hoja de 1024." },
  "Green is −Y (DirectX) but the engine reads OpenGL: the relief looks inverted.": { ca: "El verd és −Y (DirectX) però el motor llegeix OpenGL: el relleu es veu invertit.", es: "El verde es −Y (DirectX) pero el motor lee OpenGL: el relieve se ve invertido." },
  "Green is +Y (OpenGL) but Unreal reads DirectX (−Y): the relief looks inverted.": { ca: "El verd és +Y (OpenGL) però Unreal llegeix DirectX (−Y): el relleu es veu invertit.", es: "El verde es +Y (OpenGL) pero Unreal lee DirectX (−Y): el relieve se ve invertido." },
  "Bake Type must be Diffuse for an ID map.": { ca: "Per a un ID map, el Bake Type ha de ser Diffuse.", es: "Para un ID map, el Bake Type tiene que ser Diffuse." },
  "Selected to Active is off: the plane baked its own material.": { ca: "Selected to Active està desactivat: el pla ha fet el bake del seu propi material.", es: "Selected to Active está desactivado: el plano ha hecho el bake de su propio material." },
  "Direct or Indirect is on: light and shadow are baked into the colours.": { ca: "Direct o Indirect estan activats: la llum i l'ombra queden dins dels colors.", es: "Direct o Indirect están activados: la luz y la sombra quedan dentro de los colores." },
  "Color is off: the material colours are not baked.": { ca: "Color està desactivat: no es fa el bake dels colors dels materials.", es: "Color está desactivado: no se hace el bake de los colores de los materiales." },
